.vaxrun-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #18303a;
    background: linear-gradient(160deg, #eef6f4 0%, #e1eef2 100%);
    border-radius: 18px;
}

.vaxrun-container * {
    box-sizing: border-box;
}

.vaxrun-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0a4a5c 0%, #0e6e7a 52%, #14a08c 100%);
    color: #f1fbfa;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(10, 74, 92, 0.30);
}

.vaxrun-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.vaxrun-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #bff0e9;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.vaxrun-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #def4f1;
}

.vaxrun-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #135263;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.vaxrun-period-counter #currentDay,
.vaxrun-period-counter #maxPeriods {
    font-weight: 800;
    color: #0a4a5c;
}

.vaxrun-round-name {
    background: #d4ecec;
    color: #0a4a5c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.vaxrun-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8421b;
    background: #fbe6dd;
    padding: 4px 12px;
    border-radius: 999px;
}

.vaxrun-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.vaxrun-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6e7e9;
    box-shadow: 0 4px 14px rgba(10, 74, 92, 0.06);
    border-top: 4px solid #14a08c;
}

.vaxrun-card-coverage { border-top-color: #0b8a52; }
.vaxrun-card-equity { border-top-color: #c07a12; }
.vaxrun-card-supply { border-top-color: #2f7fb0; }
.vaxrun-card-cost { border-top-color: #6a52b0; }

.vaxrun-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5a7680;
}

.vaxrun-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0a4a5c;
}

.vaxrun-card-coverage .vaxrun-value { color: #0b8a52; }
.vaxrun-card-equity .vaxrun-value { color: #c07a12; }
.vaxrun-card-supply .vaxrun-value { color: #2f7fb0; }
.vaxrun-card-cost .vaxrun-value { color: #6a52b0; }

.vaxrun-sublabel {
    font-size: 0.76rem;
    color: #6d888f;
    line-height: 1.35;
}

.vaxrun-coverage-fail .vaxrun-value { color: #c0392b; }
.vaxrun-coverage-target .vaxrun-value { color: #0b8a52; }

.vaxrun-equity-good .vaxrun-value { color: #0b8a52; }
.vaxrun-equity-bad .vaxrun-value { color: #c0392b; }

.vaxrun-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0a4a5c;
    color: #eaf7f6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.vaxrun-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.vaxrun-budget-over #budgetDisplay {
    color: #ffb3a0;
}

.vaxrun-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #14a08c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(10, 74, 92, 0.05);
}

.vaxrun-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.vaxrun-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0a4a5c;
    margin-bottom: 6px;
}

.vaxrun-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2b4a52;
}

.vaxrun-briefing-text strong { color: #0b8a52; }
.vaxrun-briefing-text em { color: #a8421b; font-style: italic; }

.vaxrun-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6e7e9;
    box-shadow: 0 4px 14px rgba(10, 74, 92, 0.06);
}

.vaxrun-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0a4a5c;
    border-bottom: 2px solid #e1eef2;
    padding-bottom: 8px;
}

.vaxrun-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #1c424d;
    margin: 14px 0 6px;
}

.vaxrun-container select,
.vaxrun-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6d3d6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6fbfb;
    color: #18303a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.vaxrun-container select:focus,
.vaxrun-container input[type="number"]:focus {
    outline: none;
    border-color: #14a08c;
    box-shadow: 0 0 0 3px rgba(20, 160, 140, 0.15);
}

.vaxrun-container select option {
    background-color: #ffffff;
    color: #18303a;
}

.vaxrun-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #14a08c;
}

.vaxrun-range-readout,
.vaxrun-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0e6e7a;
    margin-top: 4px;
}

.vaxrun-range-readout span:last-child,
.vaxrun-alloc-readout span:nth-child(2) {
    color: #0b8a52;
    font-weight: 800;
}

.vaxrun-hint {
    font-size: 0.8rem;
    color: #6d888f;
    margin-top: 4px;
    line-height: 1.4;
}

.vaxrun-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.vaxrun-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2faf9;
    border: 1px solid #daebec;
    border-radius: 9px;
    padding: 8px 12px;
}

.vaxrun-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #1c424d;
}

.vaxrun-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.vaxrun-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.vaxrun-container .btn-primary {
    background: linear-gradient(135deg, #0b8a52 0%, #14a08c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(11, 138, 82, 0.28);
}

.vaxrun-container .btn-primary:hover {
    filter: brightness(1.06);
}

.vaxrun-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6d3d6;
    color: #5a7680;
}

.vaxrun-coach {
    background: #0a4a5c;
    color: #eaf7f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(10, 74, 92, 0.22);
}

.vaxrun-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #84d2c7;
    margin-bottom: 8px;
}

.vaxrun-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.vaxrun-coach-body strong { color: #ffe09a; }
.vaxrun-coach-body em { color: #ffc1ad; font-style: italic; }

.vaxrun-history,
.vaxrun-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6e7e9;
    box-shadow: 0 4px 14px rgba(10, 74, 92, 0.06);
}

.vaxrun-history h3,
.vaxrun-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0a4a5c;
}

.vaxrun-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #1c424d;
}

.vaxrun-container table#usfHistoryTable th {
    background: #e9f4f4;
    color: #0a4a5c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2e6e6;
}

.vaxrun-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4f4;
}

.vaxrun-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fbfb;
}

.vaxrun-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .vaxrun-container {
        padding: 14px;
    }
    .vaxrun-header h1 {
        font-size: 1.7rem;
    }
    .vaxrun-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .vaxrun-value {
        font-size: 2rem;
    }
    .vaxrun-clock {
        margin-left: 0;
    }
    .vaxrun-period-counter {
        font-size: 0.88rem;
    }
    .vaxrun-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .vaxrun-alloc-row {
        flex-wrap: wrap;
    }
    .vaxrun-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .vaxrun-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (append-only, dark-on-light) ===== */
.vaxrun-completion { color:#1f2d33; font-size:0.95rem; }
.vaxrun-cm-head { text-align:center; margin-bottom:16px; }
.vaxrun-cm-score { font-size:3.2rem; font-weight:800; line-height:1; color:#1f6f8b; }
.vaxrun-cm-score-max { font-size:1.2rem; font-weight:600; color:#5a9bb0; }
.vaxrun-cm-grade { font-size:1.2rem; font-weight:700; margin-top:6px; color:#14293a; }
.vaxrun-cm-badge { display:inline-block; margin-left:6px; padding:2px 10px; border-radius:999px; font-size:0.78rem; font-weight:700; vertical-align:middle; }
.vaxrun-cm-yes { background:rgba(31,111,139,0.14); color:#1a6076; border:1px solid rgba(31,111,139,0.5); }
.vaxrun-cm-no { background:rgba(201,138,22,0.16); color:#8a6a1f; border:1px solid rgba(201,138,22,0.5); }
.vaxrun-cm-fail { background:rgba(192,57,43,0.12); color:#b0392b; border:1px solid rgba(192,57,43,0.45); }
.vaxrun-cm-metrics { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin:12px 0 16px; }
.vaxrun-cm-metric { flex:1 1 110px; min-width:100px; background:rgba(20,41,58,0.06); border:1px solid rgba(20,41,58,0.16); border-radius:10px; padding:10px 8px; text-align:center; }
.vaxrun-cm-mv { display:block; font-size:1.4rem; font-weight:800; color:#1f3346; }
.vaxrun-cm-ml { display:block; font-size:0.72rem; margin-top:4px; color:#5a7680; text-transform:uppercase; letter-spacing:0.03em; }
.vaxrun-cm-insights-title { font-weight:700; margin:8px 0 6px; color:#14293a; }
.vaxrun-cm-insights { margin:0; padding-left:20px; }
.vaxrun-cm-insights li { margin:4px 0; color:#2b3f4b; }

