(function() {
    'use strict';

    class VaccineRunAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Vaccine Run`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_COVERAGE = 80;       // current-trajectory projection before your decisions
            this.TARGET_COVERAGE = 90;      // funder target
            this.NATIONAL_STRETCH = 95;     // stretch
            this.START_EQUITY = 19;         // hill vs urban gap, pts (lower better)
            this.TARGET_EQUITY = 8;         // acceptable closed gap
            this.START_SUPPLY = 172;        // nominal children coverable (thousands)
            this.START_COST = 180;          // ₹ per dose delivered (lower better)
            this.BUDGET_CAP = 3.8;          // ₹ crore fixed envelope

            // Concept-correct answers.
            this.TRUE_FAILURE = `wastage`;
            this.TRUE_SUPPLYBASE = `effective`;
            this.TRUE_SERVICE = `equity`;
            this.TRUE_VIAL = `smallvial`;
            this.TRUE_TRIAGE = `equity`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coverage: this.START_COVERAGE,
                    equityGap: this.START_EQUITY,
                    effSupply: this.START_SUPPLY,
                    costPerDose: this.START_COST,
                    budgetUsed: 0,
                    overran: false,
                    threwAwayEquity: false,
                    coldChainBreach: false,
                    coverageHistory: [this.START_COVERAGE],
                    equityHistory: [this.START_EQUITY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately MIDDLING — not the textbook play.
                state.decisions = {
                    failure: `pullers`,
                    supplyBase: `nominal`,
                    focus: 50,
                    service: `uniform`,
                    edge: 50,
                    central: 50,
                    vial: `keep10`,
                    route: `hubspoke`,
                    cycles: 4,
                    cold: 50,
                    triage: `age`,
                    shock: `freeze`,
                    overrun: `within`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const f = document.getElementById(`failureInput`);
                const sb = document.getElementById(`supplyBaseInput`);
                const fo = document.getElementById(`focusInput`);
                if (f) decisions.failure = f.value;
                if (sb) decisions.supplyBase = sb.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const sv = document.getElementById(`serviceInput`);
                const vi = document.getElementById(`vialInput`);
                if (sv) decisions.service = sv.value;
                if (vi) decisions.vial = vi.value;
                const edge = document.getElementById(`edgeInput`);
                const central = document.getElementById(`centralInput`);
                if (edge) decisions.edge = parseFloat(edge.value);
                if (central) decisions.central = parseFloat(central.value);
                if (!Number.isFinite(decisions.edge) || !Number.isFinite(decisions.central) || decisions.edge < 0 || decisions.central < 0) {
                    warn(`warn_buffer_negative`); return false;
                }
                const total = Math.round(decisions.edge + decisions.central);
                if (total !== 100) {
                    warn(`warn_buffer_total`); return false;
                }
            } else if (round === 3) {
                const rt = document.getElementById(`routeInput`);
                const cy = document.getElementById(`cyclesInput`);
                const cd = document.getElementById(`coldInput`);
                if (rt) decisions.route = rt.value;
                if (cy) decisions.cycles = parseInt(cy.value, 10);
                if (cd) decisions.cold = parseInt(cd.value, 10);
                if (!Number.isFinite(decisions.cycles) || decisions.cycles < 0 || decisions.cycles > 20) {
                    warn(`warn_cycles_range`); return false;
                }
                if (!Number.isFinite(decisions.cold) || decisions.cold < 0 || decisions.cold > 100) {
                    warn(`warn_cold_range`); return false;
                }
            } else if (round === 4) {
                const tr = document.getElementById(`triageInput`);
                const sh = document.getElementById(`shockInput`);
                const ov = document.getElementById(`overrunInput`);
                const cv = document.getElementById(`convictionInput`);
                if (tr) decisions.triage = tr.value;
                if (sh) decisions.shock = sh.value;
                if (ov) decisions.overrun = ov.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: coverage up = good; equity gap DOWN = good; supply up = good;
            // cost DOWN = good; spend draws the ₹3.8 cr envelope.
            let coverageDelta = 0, equityDelta = 0, supplyDelta = 0, costDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the network. The real first failure is open-vial wastage
                // shrinking effective supply (Key Concept: effective ≠ nominal).
                if (d.failure === this.TRUE_FAILURE) {
                    supplyDelta += 3; coverageDelta += 1; coachKey = `coach_r1_wastage`;
                } else if (d.failure === `pullers`) {
                    // Real but secondary — a symptom, not the structural leak. Partial credit
                    // only: it leaves the open-vial wastage that shrinks effective supply unseen,
                    // so it must score strictly below naming wastage as the failure point.
                    equityDelta -= 1; coverageDelta -= 1; coachKey = `coach_r1_pullers`;
                } else if (d.failure === `capacity`) {
                    coverageDelta -= 2; coachKey = `coach_r1_capacity`;
                } else {
                    coverageDelta -= 3; coachKey = `coach_r1_staffing`;
                }

                // Net wastage out of nominal supply now, vs being blindsided later.
                if (d.supplyBase === this.TRUE_SUPPLYBASE) {
                    supplyDelta += 6; coverageDelta += 2;
                    if (d.failure === this.TRUE_FAILURE) coachKey = `coach_r1_sharp`;
                } else if (d.supplyBase === `nominal`) {
                    supplyDelta -= 6; coverageDelta -= 2; coachKey = `coach_r1_nominal`;
                } else {
                    supplyDelta -= 10; coverageDelta -= 4; coachKey = `coach_r1_optimistic`;
                }

                // Diagnostic focus on the real leverage point.
                if (d.focus >= 60) { coverageDelta += 1; }
                else if (d.focus <= 25) { coverageDelta -= 3; }

                summaryKey = (d.failure === this.TRUE_FAILURE && d.supplyBase === this.TRUE_SUPPLYBASE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Inventory & safety stock under a service-level objective.
                // Equity-weighted service closes the gap; throughput widens it (Common Error 1).
                switch (d.service) {
                    case `equity`: coverageDelta += 2; equityDelta -= 4; coachKey = `coach_r2_equity`; break;
                    case `uniform`: coverageDelta += 1; equityDelta -= 2; coachKey = `coach_r2_uniform`; break;
                    case `urban`: coverageDelta += 2; equityDelta += 3; coachKey = `coach_r2_urban`; break;
                }

                // Edge vs central buffer. Hill blocks cannot be resupplied mid-week, so an
                // edge-weighted buffer protects them; over-centralising starves them (Common Error 3).
                const edge = d.edge;
                if (edge >= 65 && edge <= 80) {
                    coverageDelta += 1; equityDelta -= 3; coachKey = `coach_r2_edgeright`;
                } else if (edge > 80) {
                    // Too far to the edge: thin sessions raise wastage risk.
                    coverageDelta += 1; equityDelta -= 1; supplyDelta -= 2; coachKey = `coach_r2_alledge`;
                } else if (edge <= 35) {
                    coverageDelta -= 3; equityDelta += 3; coachKey = `coach_r2_central`;
                } else {
                    coverageDelta += 1; equityDelta -= 1;
                }

                // Multi-dose vial handling drives open-vial wastage (Common Error 2).
                switch (d.vial) {
                    case `smallvial`: spend += 0.35; supplyDelta += 7; costDelta -= 6; coachKey = (edge >= 65 && edge <= 80) ? `coach_r2_lever` : coachKey; break;
                    case `keep10`: supplyDelta -= 2; coachKey = `coach_r2_keep`; break;
                    case `overship`: supplyDelta -= 8; costDelta += 12; coachKey = `coach_r2_overship`; break;
                }

                summaryKey = (d.service === this.TRUE_SERVICE && d.vial === this.TRUE_VIAL && edge >= 55) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Distribution routing within capacity, budget, and the cold-chain clock.
                // Cost-only hub-and-spoke breaches the cold chain on the hill leg (Common Error 4).
                switch (d.route) {
                    case `mixed`: spend += 1.9; coverageDelta += 2; equityDelta -= 2; costDelta -= 4; coachKey = `coach_r3_mixed`; break;
                    case `dedicated`: spend += 2.6; coverageDelta += 1; equityDelta -= 3; coachKey = `coach_r3_dedicated`; break;
                    case `hubspoke`:
                        // Cheap transport but doses arrive non-viable past the 4-hour breach.
                        spend += 1.1; coverageDelta -= 4; equityDelta += 3; costDelta += 14;
                        supplyDelta -= 4; ds.coldChainBreach = true; coachKey = `coach_r3_hub`; break;
                }

                // Extra dedicated remote cycles buy hill coverage at ₹0.62 lakh each (₹0.0062 cr).
                const cycles = d.cycles;
                spend += cycles * 0.0062;
                if (cycles >= 4 && cycles <= 10) {
                    coverageDelta += 1; equityDelta -= 2;
                } else if (cycles > 10) {
                    // Over-buying cycles: diminishing coverage, real budget burn.
                    coverageDelta += 1; equityDelta -= 2; costDelta += 3; coachKey = `coach_r3_toomany`;
                } else {
                    equityDelta += 2; coachKey = (d.route === `hubspoke`) ? coachKey : `coach_r3_nocycles`;
                }

                // Cold-chain protection effort. Low effort destroys doses on arrival.
                if (d.cold >= 60) { coverageDelta += 1; supplyDelta += 2; costDelta -= 3; }
                else if (d.cold <= 25) { coverageDelta -= 4; supplyDelta -= 3; costDelta += 8; ds.coldChainBreach = true; coachKey = `coach_r3_coldfail`; }

                summaryKey = (d.route !== `hubspoke` && d.cold >= 50 && cycles >= 4) ? `sum_r3_good` : (d.route === `hubspoke` || d.cold <= 25 ? `sum_r3_breach` : `sum_r3_weak`);
            } else if (round === 4) {
                // Write the triage rule & recover under a mid-campaign shock.
                // An explicit equity rule beats FCFS (which is itself a regressive rule).
                switch (d.triage) {
                    case `equity`: coverageDelta += 2; equityDelta -= 2; coachKey = `coach_r4_equity`; break;
                    case `age`: coverageDelta += 1; equityDelta -= 1; coachKey = `coach_r4_age`; break;
                    case `fcfs`: coverageDelta -= 2; equityDelta += 4; coachKey = `coach_r4_fcfs`; break;
                    case `none`: coverageDelta -= 4; equityDelta += 5; coachKey = `coach_r4_none`; break;
                }

                // Response to the day-22 shock. Holding a rule built for this is the point.
                switch (d.shock) {
                    case `reallocate`: coverageDelta += 1; equityDelta -= 2; coachKey = (d.triage === `equity`) ? `coach_r4_held` : coachKey; break;
                    case `freeze`: coverageDelta -= 2; coachKey = `coach_r4_freeze`; break;
                    case `abandon`: coverageDelta += 2; equityDelta += 6; ds.threwAwayEquity = true; coachKey = `coach_r4_abandon`; break;
                }

                // Budget discipline. Overrun borrows coverage from next quarter's infants.
                switch (d.overrun) {
                    case `within`: costDelta -= 4; break;
                    case `small`: spend += 0.2; coverageDelta += 1; break;
                    case `blow`: spend += 1.4; coverageDelta += 3; costDelta += 10; ds.overran = true; coachKey = `coach_r4_blow`; break;
                }

                // Conviction nudges coverage (a defensible, owned plan).
                coverageDelta += Math.round((d.conviction - 60) / 25);

                summaryKey = (d.triage === this.TRUE_TRIAGE && d.shock === `reallocate` && d.overrun !== `blow`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (₹ crore). Budget can be exceeded — the cap binds in scoring.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;

            // Apply deltas with headroom-preserving clamps.
            ds.coverage = Math.max(0, Math.min(100, ds.coverage + coverageDelta));
            ds.equityGap = Math.max(0, Math.min(40, ds.equityGap + equityDelta));
            ds.effSupply = Math.max(0, Math.round(ds.effSupply + supplyDelta));
            ds.costPerDose = Math.max(40, Math.round(ds.costPerDose + costDelta));

            // Overrun penalty: spending past ₹3.8 cr lifts the true cost per dose
            // (coverage borrowed from routine immunisation).
            if (ds.budgetUsed > this.BUDGET_CAP) {
                ds.overran = true;
                ds.costPerDose = Math.round(ds.costPerDose + (ds.budgetUsed - this.BUDGET_CAP) * 30);
            }

            ds.coverageHistory.push(Math.round(ds.coverage));
            ds.equityHistory.push(Math.round(ds.equityGap));
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                coverage: Math.round(ds.coverage),
                coverageDelta: Math.round(coverageDelta),
                equityGap: Math.round(ds.equityGap),
                equityDelta: Math.round(equityDelta),
                effSupply: ds.effSupply,
                costPerDose: ds.costPerDose,
                budgetUsed: ds.budgetUsed,
                overran: ds.overran,
                coldChainBreach: ds.coldChainBreach,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`coverageDisplay`, `domainState.coverage`, (v) => {
