            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.vaxrun-budget-bar`);
                if (card) card.classList.toggle(`vaxrun-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `₹` + Number(v).toFixed(2) + ` cr / ₹3.80 cr`;
            });

            const self = this;

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Cold-chain slider readout.
            const cd = document.getElementById(`coldInput`);
            const cdReadout = document.getElementById(`coldReadout`);
            if (cd && cdReadout) {
                cdReadout.textContent = cd.value;
                cd.addEventListener(`input`, function() { cdReadout.textContent = cd.value; });
            }

            // Buffer split: keep edge + central = 100, live total readout.
            const edgeEl = document.getElementById(`edgeInput`);
            const centralEl = document.getElementById(`centralInput`);
            const bufferReadout = document.getElementById(`bufferReadout`);
            const recompute = function(changed) {
                let edge = edgeEl ? (parseFloat(edgeEl.value) || 0) : 0;
                let central = centralEl ? (parseFloat(centralEl.value) || 0) : 0;
                // Auto-mirror the counterpart so the pair always sums to 100.
                if (changed === `edge` && centralEl) { central = Math.max(0, 100 - edge); centralEl.value = central; }
                else if (changed === `central` && edgeEl) { edge = Math.max(0, 100 - central); edgeEl.value = edge; }
                const total = Math.round(edge + central);
                if (bufferReadout) bufferReadout.textContent = total;
                const bar = document.querySelector(`.vaxrun-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            if (edgeEl) edgeEl.addEventListener(`input`, function() { recompute(`edge`); });
            if (centralEl) centralEl.addEventListener(`input`, function() { recompute(`central`); });
            recompute();
        }

        _composite(ds) {
            const coverage = Math.round(ds.coverage);
            const equityGap = Math.round(ds.equityGap);
            const effSupply = ds.effSupply;
            const cost = ds.costPerDose;
            const onBudget = ds.budgetUsed <= this.BUDGET_CAP + 0.001;
            const coverageScore = Math.min(100, coverage);
            const equityScore = Math.max(0, 100 - equityGap * 4);
            const supplyScore = Math.max(0, Math.min(100, (effSupply - 145) / (192 - 145) * 100));
            const costScore = Math.max(0, Math.min(100, 100 - (cost - 150) / (260 - 150) * 100));
            const budgetScore = onBudget ? 100 : Math.max(0, 100 - (ds.budgetUsed - this.BUDGET_CAP) * 80);
            let compositeRaw = coverageScore * 0.34 + equityScore * 0.28 + supplyScore * 0.14 + costScore * 0.12 + budgetScore * 0.12;
            if (ds.coldChainBreach) compositeRaw -= 6;
            return Math.round(Math.max(0, Math.min(100, compositeRaw)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

