        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const coverage = Math.round(ds.coverage);
            const equityGap = Math.round(ds.equityGap);
            const effSupply = ds.effSupply;
            const cost = ds.costPerDose;

            const hitTarget = coverage >= this.TARGET_COVERAGE;
            const closedGap = equityGap <= this.TARGET_EQUITY;
            const onBudget = ds.budgetUsed <= this.BUDGET_CAP + 0.001;
            // Composite weights all four decision-relevant KPIs so every Common Error is scored,
            // not just coverage/equity. Effective supply captures the open-vial wastage lever
            // (Common Error 2) and cost-per-dose-delivered captures cost-only routing / budget
            // blow (Common Errors 4 & 6) — both were previously computed but never scored, which
            // let those levers stay cosmetic once coverage saturated. A cold-chain breach is a
            // hard-constraint failure, so it carries an explicit penalty.
            const composite = this._composite(ds);

            let performanceKey = `grade_risk`;
            if (hitTarget && closedGap && onBudget && composite >= 80) performanceKey = `grade_equitable`;
            else if (hitTarget && closedGap && onBudget) performanceKey = `grade_targethit`;
            else if (hitTarget && !onBudget) performanceKey = `grade_blown`;
            else if (hitTarget && !closedGap) performanceKey = `grade_equitylost`;
            else if (coverage >= this.START_COVERAGE + 4) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && closedGap && onBudget) insights.push(window.mySimulation.t(`insight_equitable`));
            else if (hitTarget && !onBudget) insights.push(window.mySimulation.t(`insight_overran`));
            else if (hitTarget && !closedGap) insights.push(window.mySimulation.t(`insight_throughput`));
            else if (!hitTarget) insights.push(window.mySimulation.t(`insight_short`));

            if (ds.coldChainBreach) insights.push(window.mySimulation.t(`insight_coldchain`));
            if (ds.threwAwayEquity) insights.push(window.mySimulation.t(`insight_abandoned`));
            if (effSupply < this.START_SUPPLY - 4) insights.push(window.mySimulation.t(`insight_wastage`));
            if (coverage >= this.NATIONAL_STRETCH && closedGap) insights.push(window.mySimulation.t(`insight_stretch`));
            insights.push(window.mySimulation.t(`insight_costline`));

            return {
                coverage: coverage,
                equityGap: equityGap,
                effSupply: effSupply,
                cost: cost,
                budgetUsed: ds.budgetUsed,
                hitTarget: hitTarget,
                closedGap: closedGap,
                onBudget: onBudget,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                sound: (hitTarget && closedGap && onBudget),
                coldChainBreach: ds.coldChainBreach,
                threwAwayEquity: ds.threwAwayEquity,
                overran: ds.overran,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="vaxrun-cm-badge vaxrun-cm-yes">` + T(`cm_equitable`) + `</span>`
                : `<span class="vaxrun-cm-badge vaxrun-cm-no">` + T(`cm_notequitable`) + `</span>`;
            let failBadges = ``;
            if (s.coldChainBreach) failBadges += ` <span class="vaxrun-cm-badge vaxrun-cm-fail">` + T(`cm_coldchain`) + `</span>`;
            if (s.threwAwayEquity) failBadges += ` <span class="vaxrun-cm-badge vaxrun-cm-fail">` + T(`cm_equitylost`) + `</span>`;
            if (s.overran) failBadges += ` <span class="vaxrun-cm-badge vaxrun-cm-fail">` + T(`cm_overran`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="vaxrun-cm-metric"><span class="vaxrun-cm-mv">` + Math.round(s.coverage || 0) + `%</span><span class="vaxrun-cm-ml">` + T(`cm_m_coverage`) + `</span></div>`
                + `<div class="vaxrun-cm-metric"><span class="vaxrun-cm-mv">` + Math.round(s.equityGap || 0) + `</span><span class="vaxrun-cm-ml">` + T(`cm_m_equity`) + `</span></div>`
                + `<div class="vaxrun-cm-metric"><span class="vaxrun-cm-mv">` + Math.round(s.effSupply || 0) + `</span><span class="vaxrun-cm-ml">` + T(`cm_m_supply`) + `</span></div>`
                + `<div class="vaxrun-cm-metric"><span class="vaxrun-cm-mv">₹` + Math.round(s.cost || 0) + `</span><span class="vaxrun-cm-ml">` + T(`cm_m_cost`) + `</span></div>`;
            return ``
                + `<div class="vaxrun-completion">`
                +   `<div class="vaxrun-cm-head">`
                +     `<div class="vaxrun-cm-score">` + score + `<span class="vaxrun-cm-score-max">/100</span></div>`
                +     `<div class="vaxrun-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="vaxrun-cm-metrics">` + metrics + `</div>`
                +   `<div class="vaxrun-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="vaxrun-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.budgetUsed > this.BUDGET_CAP) return window.mySimulation.t(`hint_budget`);
            if (ds.coldChainBreach && state.currentPeriod >= 3) return window.mySimulation.t(`hint_coldchain`);
            if (ds.equityGap >= this.START_EQUITY - 2 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_equity`);
            if (ds.effSupply < this.START_SUPPLY - 4) return window.mySimulation.t(`hint_supply`);
            if (state.currentPeriod >= 3 && ds.coverage < 86) return window.mySimulation.t(`hint_behind`);
            if (ds.coverage >= this.TARGET_COVERAGE && ds.equityGap <= this.TARGET_EQUITY) return window.mySimulation.t(`hint_strong`);
            return null;
        }

